import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import SnackBar from "@/components/SnackBar.vue";
import RequestAccess from "@/components/DashBoard/Popups/RequestAccess.vue";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { list_all_dashboards } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  mixins: [get_all_org_users],
  components: {
    RequestAccess,
    SnackBar
  },
  data() {
    return {
      nextToken: null,
      searchQuery: "",
      accessingdashboard: false,
      SnackBarComponent: {},
      componentCheck: 0,
      dashboardLoading: false,
      dashboardHeaders: [{
        title: "Name",
        key: "dashboard_name",
        sortable: false
      }, {
        title: "Description",
        key: "dashboard_description",
        sortable: false
      }, {
        title: "Subscribe Count",
        key: "subscribe_counts",
        sortable: false
      }, {
        title: "Created By",
        key: "dashboard_created_by",
        sortable: false
      }, {
        title: "Actions",
        key: "Actions",
        sortable: false
      }],
      dashboardData: [],
      allUSersNames: [],
      rowInfo: {},
      totalCount: 0,
      currentPage: 1,
      itemsPerPage: 20,
      hasMoreData: true,
      pageCount: 0,
      windowHeight: 0
    };
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 280;
    await Promise.all([this.fetch_dashboard_details(), this.get_all_org_users()]);
    this.allUSersNames = this.orgUsers;
  },
  methods: {
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      // Reset pagination state
      this.nextToken = null;
      this.dashboardData = [];
      this.currentPage = 1;
      this.hasMoreData = true;
      this.accessingdashboard = false;
      // Fetch fresh data
      this.fetch_dashboard_details();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    dashboardaccess(item) {
      this.componentCheck = 1;
      this.accessingdashboard = true;
      this.rowInfo = item;
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      return name;
    },
    filterDashboardData(data, userId) {
      return data.filter(dashboard => {
        // console.log(dashboard.dashboard_visibility);
        const {
          visible_type,
          visible_members
        } = dashboard.dashboard_visibility || {};
        if (visible_type === "ALL_MEMBERS") {
          return false;
        } else if (visible_type === "RESTRICTED_MEMBERS" && visible_members && visible_members.includes(userId)) {
          return false;
        }
        return true;
      });
    },
    async fetch_dashboard_details() {
      this.dashboardLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        // Reset data when fetching fresh
        if (!this.nextToken) {
          this.dashboardData = [];
        }
        let result = await API.graphql(graphqlOperation(list_all_dashboards, {
          input: {
            limit: 50,
            nextToken: this.nextToken,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.list_all_dashboards);
        if (response.Status == "SUCCESS") {
          this.nextToken = response.nextToken;

          // Concatenate new items with existing data
          let array = this.dashboardData.concat(response.data);
          this.dashboardData = array;

          // Remove duplicates
          const uniqueArrayOfObjects = this.dashboardData.filter((obj, index, self) => index === self.findIndex(o => o.dashboard_id === obj.dashboard_id));
          this.dashboardData = uniqueArrayOfObjects;

          // Sort by sort_range
          this.dashboardData.sort((a, b) => b.sort_range - a.sort_range);

          // Filter dashboards based on visibility
          this.dashboardData = this.filterDashboardData(this.dashboardData, this.$store.getters.GetUserObj.user.user_id);

          // If there's more data, fetch it recursively
          if (this.nextToken && response.data.length > 0) {
            await this.fetch_dashboard_details();
          } else {
            this.dashboardLoading = false;
            this.hasMoreData = false;
          }
        } else {
          this.dashboardLoading = false;
        }
      } catch (error) {
        this.dashboardData = [];
        this.dashboardLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.dashboardData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.dashboardData.filter(dashboard => dashboard.dashboard_name?.toLowerCase().includes(searchTerm) || dashboard.dashboard_description?.toLowerCase().includes(searchTerm) || this.fetch_user_name(dashboard.dashboard_created_by)?.toLowerCase().includes(searchTerm) || (dashboard.subscribe_counts ? String(dashboard.subscribe_counts).toLowerCase().includes(searchTerm) : false));
    },
    totalCount() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  }
};
